        final LocatableBlock locatable = new SpongeLocatableBlockBuilder().world(apiWorld).position(pos.getX(), pos.getY(), pos.getZ()).state((BlockState)block).build();
        final BlockTickContext phaseContext = TickPhase.Tick.BLOCK.createPhaseContext(PhaseTracker.SERVER).source(locatable);

        // We have to associate any notifiers in case of scheduled block updates from other sources
        final PhaseContext<@NonNull ?> currentContext = PhaseTracker.getInstance().getPhaseContext();
        currentContext.appendNotifierPreBlockTick(world, pos, phaseContext);
        // Now actually switch to the new phase

        try (final PhaseContext<@NonNull ?> context = phaseContext) {
            context.buildAndSwitch();
            PhaseTracker.LOGGER.trace(TrackingUtil.BLOCK_TICK, () -> "Wrapping Block Tick: " + block.toString());
            tick.run();
        } catch (final Exception | NoClassDefFoundError e) {
            PhasePrinter.printExceptionFromPhase(PhaseTracker.getInstance().stack, e, phaseContext);

        }
    }

@SuppressWarnings({"unused", "try"})
    public static void tickTileEntity(final BlockEntity blockEntity, final Runnable tick) {
        Objects.requireNonNull(blockEntity, "Cannot capture on a null ticking tile entity!");
        if (!((org.spongepowered.api.block.entity.BlockEntity) blockEntity).isTicking()) {
            return;
        }
        if (!((TrackableBridge) blockEntity).bridge$shouldTick()) {
            return;
        }

        final TileEntityTickContext context = TickPhase.Tick.TILE_ENTITY.createPhaseContext(PhaseTracker.SERVER).source(blockEntity);
        try (final PhaseContext<@NonNull ?> phaseContext = context) {
            if (blockEntity instanceof CreatorTrackedBridge ctb) {
                // Add notifier and owner so we don't have to perform lookups during the phases and other processing
                ctb.tracker$getNotifierUUID().ifPresent(phaseContext::notifier);
                // Allow the tile entity to validate the owner of itself. As long as the tile entity
                // chunk is already loaded and activated, and the tile entity has already loaded
                // the owner of itself.
                ctb.tracker$getCreatorUUID().ifPresent(phaseContext::creator);
            }

            // Finally, switch the context now that we have the owner and notifier
            phaseContext.buildAndSwitch();

            PhaseTracker.LOGGER.trace(TrackingUtil.BLOCK_ENTITY_TICK, () -> "Wrapping Entity Tick: " + blockEntity);
            tick.run();

            // If we know the viewers force broadcast now to associate the inventory change with its blockentity
            // otherwise the viewing players update this during their ticking
            if (blockEntity instanceof ViewableInventoryBridge vib) {
                final Set<ServerPlayer> players = vib.viewableBridge$getViewers();
                if (!players.isEmpty()) {
                    players.forEach(player -> player.containerMenu.broadcastChanges());
                }
            }

        } catch (final Exception e) {
            PhasePrinter.printExceptionFromPhase(PhaseTracker.getInstance().stack, e, context);
        }
    }

public static Block validateBlockForNeighborNotification(final ServerLevel worldServer, final BlockPos pos, @Nullable Block blockIn,
        final BlockPos otherPos, final LevelChunk chunk) {
        if (blockIn == null) {
            // If the block is null, check with the PhaseState to see if it can perform a safe way
            final PhaseContext<?> currentContext = PhaseTracker.getInstance().getPhaseContext();
            final PhaseTrackerCategory trackerConfig = SpongeConfigs.getCommon().get().phaseTracker;

            if (currentContext.state == TickPhase.Tick.TILE_ENTITY) {
                // Try to save ourselves
                final @Nullable BlockEntity source = (BlockEntity) currentContext.getSource();

                final @Nullable BlockEntityType<?> type = Optional.ofNullable(source)
                                                   .map(BlockEntity::getType)
                                                   .orElse(null);
                if (type != null) {
                    @Nullable ResourceLocation id = BlockEntityType.getKey(type);
                    if (id == null) {
                        id = ResourceLocation.parse(source.getClass().getCanonicalName());
                    }
                    final Map<String, Boolean> autoFixedTiles = trackerConfig.autoFixNullSourceBlockProvidingBlockEntities;
                    final boolean contained = autoFixedTiles.containsKey(type.toString());
                    // If we didn't map the tile entity yet, we should apply the mapping
                    // based on whether the source is the same as the TileEntity.
                    if (!contained) {
                        autoFixedTiles.put(id.toString(), pos.equals(source.getBlockPos()));
                    }
                    final boolean useTile = contained && autoFixedTiles.get(id.toString());
                    if (useTile) {
                        blockIn = source.getBlockState().getBlock();
                    } else {
                        blockIn = (pos.getX() >> 4 == chunk.getPos().x && pos.getZ() >> 4 == chunk.getPos().z)
                                      ? chunk.getBlockState(pos).getBlock()
                                      : worldServer.getBlockState(pos).getBlock();
                    }
                    if (!contained && trackerConfig.reportNullSourceBlocksOnNeighborNotifications) {
                        PhasePrinter.printNullSourceBlockWithTile(pos, blockIn, otherPos, id, useTile, new NullPointerException("Null Source Block For TileEntity Neighbor Notification"));
                    }
                } else {
                    blockIn = (pos.getX() >> 4 == chunk.getPos().x && pos.getZ() >> 4 == chunk.getPos().z)
                                  ? chunk.getBlockState(pos).getBlock()
                                  : worldServer.getBlockState(pos).getBlock();
                    if (trackerConfig.reportNullSourceBlocksOnNeighborNotifications) {
                        PhasePrinter.printNullSourceBlockNeighborNotificationWithNoTileSource(pos, blockIn, otherPos,
                            new NullPointerException("Null Source Block For Neighbor Notification"));
                    }
                }

            } else {
                blockIn = (pos.getX() >> 4 == chunk.getPos().x && pos.getZ() >> 4 == chunk.getPos().z)
                              ? chunk.getBlockState(pos).getBlock()
                              : worldServer.getBlockState(pos).getBlock();
                if (trackerConfig.reportNullSourceBlocksOnNeighborNotifications) {
                    PhasePrinter.printNullSourceForBlock(worldServer, pos, blockIn, otherPos, new NullPointerException("Null Source Block For Neighbor Notification"));
                }
            }
        }
        return blockIn;
    }

public CompletableFuture<Void> enqueueWork(Runnable runnable) {
            var executor = LogicalSidedProvider.WORKQUEUE.get(isClientSide());

            // Must check ourselves as Minecraft will sometimes delay tasks even when they are received on the client thread
            // Same logic as ThreadTaskExecutor#runImmediately without the join
            if (!executor.isSameThread())
                return executor.submitAsync(runnable); // Use the internal method so thread check isn't done twice
            else {
                runnable.run();
                return CompletableFuture.completedFuture(null);
            }
        }

