        throw new IllegalStateException("ChatQueue has already been closed");
      }
      MinecraftConnection smc = player.ensureAndGetCurrentServer().ensureConnected();
      head = head.thenCompose(v -> {
        if (closed) {
          return CompletableFuture.completedFuture(null);
        }
        try {
          return task.update(chatState, smc).exceptionally(ignored -> null);
        } catch (Throwable ignored) {
          return CompletableFuture.completedFuture(null);
        }
      });
    }
  }

@Override
    protected void preTick() {
        this.lock.lock();
        try {
            // If we have something that has indicated it needs to change,
            // don't await, just continue.
            if (!this.stateChanged.get()) {
                this.condition.await(this.minimumTimeout, TimeUnit.NANOSECONDS);
            }
            // We're processing now. Set to false.
            this.stateChanged.set(false);
        } catch (final InterruptedException ignored) {
            // The taskMap has been modified; there is work to do.
            // Continue on without handling the Exception.
        } catch (final IllegalMonitorStateException e) {
            SpongeCommon.logger().error("The scheduler internal state machine suffered a catastrophic error", e);
        }
    }

void parsePending() { // Paper
        CraftTask head = this.head;
        CraftTask task = head.getNext();
        CraftTask lastTask = head;
        for (; task != null; task = (lastTask = task).getNext()) {
            if (task.getTaskId() == -1) {
                task.run();
            } else if (task.getPeriod() >= CraftTask.NO_REPEATING) {
                this.pending.add(task);
                this.runners.put(task.getTaskId(), task);
            }
        }
        // We split this because of the way things are ordered for all of the async calls in CraftScheduler
        // (it prevents race-conditions)
        for (task = head; task != lastTask; task = head) {
            head = task.getNext();
            task.setNext(null);
        }
        this.head = lastTask;
    }

public void removeAndFailAll(Throwable cause) {
        assert executor.inEventLoop();
        ObjectUtil.checkNotNull(cause, "cause");
        // It is possible for some of the failed promises to trigger more writes. The new writes
        // will "revive" the queue, so we need to clean them up until the queue is empty.
        for (PendingWrite write = head; write != null; write = head) {
            head = tail = null;
            size = 0;
            bytes = 0;
            while (write != null) {
                PendingWrite next = write.next;
                ReferenceCountUtil.safeRelease(write.msg);
                ChannelPromise promise = write.promise;
                recycle(write, false);
                safeFail(promise, cause);
                write = next;
            }
        }
        assertEmpty();
    }

private void startTask(final SpongeScheduledTask task) {
        this.executeRunnable(() -> {
            task.setState(SpongeScheduledTask.ScheduledTaskState.EXECUTING);
            try (final @Nullable PhaseContext<@NonNull ?> context = this.createContext(task, task.task().plugin())) {
                if (context != null) {
                    context.buildAndSwitch();
                }
                try {
                    task.task.executor().accept(task);
                } catch (final Throwable t) {
                    SpongeCommon.logger().error("The Scheduler tried to run the task '{}' owned by '{}' but an error occurred.",
                            task.name(), task.task().plugin().metadata().id(), t);
                }
            } finally {
                if (!task.isCancelled()) {
                    task.setState(SpongeScheduledTask.ScheduledTaskState.RUNNING);
                }
                this.onTaskCompletion(task);
            }
        });
    }

@Override
    public void run() {
      container.getExecutorService().execute(() -> {
        currentTaskThread = Thread.currentThread();
        try {
          if (runnable != null) {
            runnable.run();
          } else {
            consumer.accept(this);
          }
        } catch (Throwable e) {
          //noinspection ConstantConditions
          if (e instanceof InterruptedException) {
            Thread.currentThread().interrupt();
          } else {
            String friendlyPluginName = container.getDescription().getName()
                .orElse(container.getDescription().getId());
            Object unit = consumer == null ? runnable : consumer;
            Log.logger.error("Exception in task {} by plugin {}", unit, friendlyPluginName,
                e);
          }
        } finally {
          if (repeat == 0) {
            onFinish();
          }
          currentTaskThread = null;
        }
      });
    }

private void handleTask(TaskImpl task) {
        TaskSchedule schedule;
        try {
            schedule = task.task().get();
        } catch (Throwable t) {
            MinecraftServer.getExceptionManager().handleException(new RuntimeException("Exception in scheduled task", t));
            schedule = TaskSchedule.stop();
        }

        switch (schedule) {
            case TaskScheduleImpl.DurationSchedule durationSchedule -> {
                final Duration duration = durationSchedule.duration();
                var _ = SCHEDULER.schedule(() -> safeExecute(task), duration.toMillis(), TimeUnit.MILLISECONDS);
            }
            case TaskScheduleImpl.TickSchedule tickSchedule -> {
                synchronized (this) {
                    final int target = tickState + tickSchedule.tick();
                    var targetTaskQueue = switch (task.executionType()) {
                        case TICK_START -> tickStartTaskQueue;
                        case TICK_END -> tickEndTaskQueue;
                    };
                    targetTaskQueue.computeIfAbsent(target, _ -> new ArrayList<>()).add(task);
                }
            }
            case TaskScheduleImpl.FutureSchedule futureSchedule -> {
                var _ = futureSchedule.future().thenRun(() -> safeExecute(task));
            }
            case TaskScheduleImpl.Park _ -> task.parked = true;
            case TaskScheduleImpl.Stop _ -> task.cancel();
            case TaskScheduleImpl.Immediate _ -> {
                if (task.executionType() == ExecutionType.TICK_END) {
                    tickEndTasksToExecute.relaxedOffer(task);
                } else tasksToExecute.relaxedOffer(task);
            }
        }
    }

public ChannelFuture removeAndWriteAll() {
        assert executor.inEventLoop();

        if (isEmpty()) {
            return null;
        }

        ChannelPromise p = invoker.newPromise();
        PromiseCombiner combiner = new PromiseCombiner(executor);
        try {
            // It is possible for some of the written promises to trigger more writes. The new writes
            // will "revive" the queue, so we need to write them up until the queue is empty.
            for (PendingWrite write = head; write != null; write = head) {
                head = tail = null;
                size = 0;
                bytes = 0;

                while (write != null) {
                    PendingWrite next = write.next;
                    Object msg = write.msg;
                    ChannelPromise promise = write.promise;
                    recycle(write, false);
                    if (!(promise instanceof VoidChannelPromise)) {
                        combiner.add(promise);
                    }
                    invoker.write(msg, promise);
                    write = next;
                }
            }
            combiner.finish(p);
        } catch (Throwable cause) {
            p.setFailure(cause);
        }
        assertEmpty();
        return p;
    }

public static void clientTick(ClientLevel level) {
        long time = level.getGameTime();
        if (time == lastTick) return;
        lastTick = time;

        // 2. process all providers as before
        var iterator = providers.iterator();
        while (iterator.hasNext()) {
            var p = iterator.next();
            RenderBuffer buffer = getOrCreateBuffer(Cast.cast(p));

            if (!p.shouldRender(Cast.cast(buffer))) {
                map.remove(p);
                iterator.remove();
                continue;
            }

            if (time % p.getUpdateFrequency() == 0) {
                buffer.tick(p);
            }
        }
    }

private void acceptChunkResult(long chunk, ChunkResult<ChunkAccess> result) {
        this.server.submit(() -> this.releaseChunk(chunk));

        if (result.isSuccess()) {
            this.okCount.getAndIncrement();
        } else {
            this.errorCount.getAndIncrement();
        }

        this.listener.update(this.okCount.get(), this.errorCount.get(), this.skippedCount.get(), this.totalCount);

        int queuedCount = this.queuedCount.decrementAndGet();
        if (queuedCount <= QUEUE_THRESHOLD) {
            this.tryEnqueueTasks();
        }

        // Help make sure pregen progress does not get completely lost if game crashes/shuts down before pregen is finished.
        if (((this.okCount.get() + this.errorCount.get()) % 1000) == 999) {
            this.server.submit(() -> {
                this.serverLevel.save(null, false, true);
            });
        }
    }

private void tryEnqueueTasks() {
        synchronized (this.queueLock) {
            if (this.stopped) {
                return;
            }

            int enqueueCount = BATCH_SIZE - this.queuedCount.get();
            if (enqueueCount <= 0) {
                return;
            }

            LongList chunks = this.collectChunks(enqueueCount);
            if (chunks.isEmpty()) {
                this.listener.complete(this.errorCount.get());
                this.stopped = true;
                return;
            }

            this.queuedCount.getAndAdd(chunks.size());

            // Keep on server thread as chunk acquiring and releasing (tickets) is not thread safe.
            this.server.submit(() -> this.enqueueChunks(chunks));
        }
    }

@Override
	public Future<?> schedule(Runnable command, Duration delay) {
		ScheduledTask scheduledTask = new ScheduledTask(command);
		scheduledTasks.add(scheduledTask);
		try {
			Future<?> future = service.schedule(scheduledTask, delay.toMillis(), TimeUnit.MILLISECONDS);
			scheduledTask.setFuture(future);
			return new TrackedFuture<>(future, scheduledTask);
		} catch (RuntimeException e) {
			scheduledTasks.remove(scheduledTask);
			throw e;
		}
	}
